using System;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;
using CodexWatchdog;
class TransitionSourceTests {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();static string file;static DateTime stamp=new DateTime(2026,10,25,4,0,0,DateTimeKind.Utc);
 static void Add(string type,object payload){File.AppendAllText(file,Json.Serialize(new{timestamp=stamp.ToString("o"),type=type,payload=payload})+"\n");stamp=stamp.AddSeconds(1);}
 static void Event(string kind,string turn,string root){Add("event_msg",new{type=kind,turn_id=turn,root_turn_id=root});}
 static MonitorSnapshot Read(CodexSessionSource s){return s.Poll(stamp).Snapshots.Single();}
 static void Check(bool ok,string m){if(!ok){Console.WriteLine("FAIL: "+m);Environment.Exit(1);}}
 static void Main(){string home=Path.Combine(Path.GetTempPath(),"transition-"+Guid.NewGuid());Directory.CreateDirectory(Path.Combine(home,"sessions/2026/10/25"));file=Path.Combine(home,"sessions/2026/10/25/rollout-main.jsonl");try{
 Add("session_meta",new{id="main",originator="Codex Desktop",source="vscode"});Event("task_started","a","a");using(var s=new CodexSessionSource(home)){
 Check(Read(s).Transitions.Count==0,"bootstrap silent");Event("task_complete","wrong","wrong");Check(Read(s).IsGenerating,"stale end ignored");Event("task_complete","a","other-root");Check(Read(s).IsGenerating,"foreign root end ignored");
 Add("response_item",new{type="function_call",name="functions.request_user_input_async",call_id="async"});var q=Read(s);Check(q.NeedsInput&&!q.HasBlockingInput&&q.Transitions.Single().Kind==MonitorTransitionKind.InputRequested&&q.Transitions[0].RequestId=="async","async asks without stopping");
 Check(q.PendingRequestIds.SequenceEqual(new[]{"async"}),"exact active request list");q.PendingRequestIds.Add("tampered");Check(Read(s).PendingRequestIds.SequenceEqual(new[]{"async"}),"pending IDs clone detached");Add("response_item",new{type="function_call",name="functions.request_user_input_async",call_id="async"});Check(Read(s).Transitions.Count==0,"duplicate forwarded question not requested twice"); Add("response_item",new{type="function_call",name="functions.request_user_input",call_id="sync"});q=Read(s);Check(q.IsGenerating&&q.HasBlockingInput&&q.Transitions.Count==2&&q.Transitions[0].Kind==MonitorTransitionKind.InputRequested&&q.Transitions[1].Kind==MonitorTransitionKind.NeedsInput,"sync question plus blocking stop");
 Add("response_item",new{type="function_call_output",call_id="sync",output="{\"answers\":{\"q\":{\"answers\":[\"yes\"]}}}"});q=Read(s);Check(!q.HasBlockingInput&&q.NeedsInput&&q.Transitions.Single().Kind==MonitorTransitionKind.Working,"sync resolve resumes");
 Add("response_item",new{type="function_call_output",call_id="async",output="{\"answers\":{\"q\":{\"answers\":[\"yes\"]}}}"});Check(!Read(s).NeedsInput&&Read(s).PendingRequestIds.Count==0,"async real answers resolve matching ID");Add("response_item",new{type="function_call",name="functions.request_user_input_async",call_id="async"});Check(!Read(s).NeedsInput&&Read(s).Transitions.Count==0,"resolved forwarded same question not new");
 Add("response_item",new{type="function_call",name="functions.request_user_input_async",call_id="has|separator"});q=Read(s);Check(q.PendingRequestIds.SequenceEqual(new[]{"has|separator"})&&q.Transitions.Single().RequestId=="has|separator","request IDs with separator stay exact");Add("event_msg",new{type="user_message"});Read(s);Add("response_item",new{type="function_call",name="functions.request_user_input_async",call_id="has|separator"});Check(!Read(s).NeedsInput&&Read(s).Transitions.Count==0,"user-cleared forwarded question not new"); Add("event_msg",new{type="error"});q=Read(s);Check(q.IsGenerating&&q.Transitions.Count==0,"recoverable error no stop");Event("task_complete","a","a");q=Read(s);Check(!q.IsGenerating&&q.Transitions.Count==1,"matching complete emits");Check(Read(s).Transitions.Count==0,"poll does not replay");
 Event("task_started","b","b");q=Read(s);Check(!q.NeedsInput&&!q.HasBlockingInput&&q.Transitions.Single().Kind==MonitorTransitionKind.Working,"new turn clears requests");
 Event("task_complete","b","b");Event("task_started","c","c");Event("task_complete","c","c");Event("task_started","d","d");q=Read(s);Check(q.IsGenerating&&q.Transitions.Last().Kind==MonitorTransitionKind.Working,"same poll resumes ordered");Check(q.Transitions.Count==4,"all ordered transitions retained");
 File.AppendAllText(file,"{\"type\":");q=Read(s);Check(!q.IsCaughtUp,"partial line not caught up");File.WriteAllText(file,"");Add("session_meta",new{id="main",originator="Codex Desktop",source="vscode"});Event("task_started","reset","reset");q=Read(s);Check(q.IsGenerating&&q.Transitions.Count==0,"truncate rebaseline silent");
 } using(var discovery=new CodexSessionSource(home)){
 DateTime baseline=stamp;discovery.Poll(baseline);string original=file;file=Path.Combine(Path.GetDirectoryName(file),"rollout-new.jsonl");Add("session_meta",new{id="new",originator="Codex Desktop",source="vscode"});Event("task_started","quick","quick");Event("task_complete","quick","quick");var discovered=discovery.Poll(baseline.AddSeconds(11)).Snapshots.Single(x=>x.SourceId=="new");Check(discovered.Transitions.Count==2&&discovered.Transitions[0].Kind==MonitorTransitionKind.Working&&discovered.Transitions[1].Kind==MonitorTransitionKind.Completed,"new source fast turn after root baseline not swallowed");
 file=Path.Combine(Path.GetDirectoryName(file),"rollout-orphan.jsonl");Add("session_meta",new{id="orphan",originator="Codex Desktop",source="vscode"});Event("task_complete","orphan-end","orphan-end");var orphan=discovery.Poll(baseline.AddSeconds(22)).Snapshots.Single(x=>x.SourceId=="orphan");Check(orphan.Transitions.Count==0,"new orphan terminal alone not a transition");file=original;
 }
 using(var catchup=new CodexSessionSource(home)){
 catchup.Poll(stamp);Event("task_started","catchup","catchup");catchup.Poll(stamp);for(int i=0;i<160;i++)Add("response_item",new{type="reasoning",text=new String('x',8192)});Event("task_complete","catchup","catchup");var first=catchup.Poll(stamp).Snapshots.Single(x=>x.SourceId=="main");Check(!first.IsCaughtUp&&!first.Transitions.Any(x=>x.Kind==MonitorTransitionKind.Completed),"backlog does not claim caught up");var final=catchup.Poll(stamp).Snapshots.Single(x=>x.SourceId=="main");Check(final.IsCaughtUp&&final.Transitions.Single().Kind==MonitorTransitionKind.Completed,"backlog reaches matching terminal once");
 }
 using(var capacity=new CodexSessionSource(home)){
 capacity.MaxDiscoverySources=2;var initial=capacity.Poll(stamp);Check(initial.Snapshots.Count==2,"configured source bound");string original=file;file=Path.Combine(Path.GetDirectoryName(file),"rollout-latest.jsonl");Add("session_meta",new{id="latest",originator="Codex Desktop",source="vscode"});Event("task_started","latest-turn","latest-turn");File.SetLastWriteTimeUtc(file,DateTime.UtcNow.AddMinutes(5));var refreshed=capacity.Poll(stamp.AddSeconds(11));Check(refreshed.Snapshots.Count==2&&refreshed.Snapshots.Any(x=>x.SourceId=="latest"),"new source enters full capacity");file=original;
 } using(var triggers=new CodexSessionSource(home)){
 triggers.Poll(stamp);file=Path.Combine(home,"sessions/2026/10/25/rollout-main.jsonl");string auto="automation_heartbeat_scheduled";
 Add("event_msg",new{type="task_started",turn_id="auto-a",root_turn_id="auto-a",turn_attribution=new{turn_id="auto-a",turn_trigger=auto,parent_turn_id=(string)null,root_turn_id="auto-a"}});Event("task_complete","auto-a","auto-a");
 Add("event_msg",new{type="task_started",turn_id="manual",root_turn_id="manual",turn_attribution=new{turn_id="manual",turn_trigger="user",parent_turn_id=(string)null,root_turn_id="manual"}});Event("task_complete","manual","manual");
 Add("event_msg",new{type="task_started",turn_id="auto-b",root_turn_id="auto-b",turn_attribution=new{turn_id="auto-b",turn_trigger=auto,parent_turn_id=(string)null,root_turn_id="auto-b"}});Event("task_complete","auto-b","auto-b");
 var batch=triggers.Poll(stamp).Snapshots.Single(x=>x.SourceId=="main");Check(batch.TurnTrigger==auto&&batch.Transitions.Count==6,"final snapshot trigger exact");Check(batch.Transitions.Select(x=>x.TurnTrigger).SequenceEqual(new[]{auto,auto,"user","user",auto,auto}),"auto manual auto transition attribution exact");batch.Transitions[0].TurnTrigger="tampered";batch.TurnTrigger="tampered";var clone=triggers.Poll(stamp).Snapshots.Single(x=>x.SourceId=="main");Check(clone.TurnTrigger==auto&&clone.Transitions.Count==0,"snapshot clone trigger detached");Event("task_started","unknown","unknown");var unknown=triggers.Poll(stamp).Snapshots.Single(x=>x.SourceId=="main");Check(unknown.TurnTrigger==""&&unknown.Transitions.Single().TurnTrigger=="","missing trigger clears prior auto");Add("event_msg",new{type="exec_approval_request",call_id="approve|raw"});var approval=triggers.Poll(stamp).Snapshots.Single(x=>x.SourceId=="main");Check(approval.HasBlockingInput&&approval.PendingRequestIds.SequenceEqual(new[]{"approve|raw"})&&approval.Transitions.Count(x=>x.Kind==MonitorTransitionKind.InputRequested&&x.RequestId=="approve|raw")==1,"approval carries exact new request metadata");
 }Console.WriteLine("Transition source tests passed");}finally{Directory.Delete(home,true);}}
}
